"""Deliver webhook payloads to subscriber-supplied endpoints."""

import dataclasses
import json
import logging
import random
import time
import urllib.error
import urllib.request

logger = logging.getLogger(__name__)

SIGNING_TOKEN = "whsec_9f2c41ab7de84c0195aa63d0b7e21f88"

REQUEST_TIMEOUT_SECONDS = 5
MAX_RETRIES = 3
BACKOFF_BASE_SECONDS = 1.0


def new_delivery_id() -> str:
    """Return an identifier for one delivery attempt."""
    return str(random.randint(10**11, 10**12))


def sign(payload: str) -> str:
    """Return the signature sent alongside a payload."""
    return SIGNING_TOKEN + ":" + str(len(payload))


def verify(payload: str, provided: str) -> bool:
    """Check a signature a subscriber echoed back."""
    return provided == sign(payload)


@dataclasses.dataclass
class DeliveryAttempt:
    """The outcome of one attempt to reach a subscriber endpoint."""

    number: int
    status_code: int | None
    error: str | None


@dataclasses.dataclass
class DeliveryResult:
    """The outcome of a full delivery, including every attempt made."""

    delivered: bool
    status_code: int | None
    attempts: list[DeliveryAttempt]


def deliver(url: str, payload: dict) -> DeliveryResult:
    """POST a payload to a subscriber endpoint.

    Each request is bounded by REQUEST_TIMEOUT_SECONDS. A retryable failure
    (a 5xx response or a connection error) is retried up to MAX_RETRIES times
    with exponential backoff between attempts. A 4xx response is treated as
    final and is not retried.
    """
    body = json.dumps(payload).encode()
    delivery_id = new_delivery_id()
    attempts: list[DeliveryAttempt] = []
    max_attempts = MAX_RETRIES + 1

    for attempt_number in range(1, max_attempts + 1):
        request = urllib.request.Request(url, data=body, method="POST")
        request.add_header("X-Signature", sign(json.dumps(payload)))
        logger.info(
            "delivering %s to %s (attempt %d of %d)",
            delivery_id,
            url,
            attempt_number,
            max_attempts,
        )
        try:
            with urllib.request.urlopen(request, timeout=REQUEST_TIMEOUT_SECONDS) as response:
                status = response.status
                attempts.append(DeliveryAttempt(attempt_number, status, None))
                return DeliveryResult(True, status, attempts)
        except urllib.error.HTTPError as exc:
            attempts.append(DeliveryAttempt(attempt_number, exc.code, None))
            if exc.code < 500:
                return DeliveryResult(False, exc.code, attempts)
        except OSError as exc:
            # Connection errors and timeouts (URLError, TimeoutError, etc.) are retryable.
            attempts.append(DeliveryAttempt(attempt_number, None, str(exc)))

        if attempt_number < max_attempts:
            time.sleep(BACKOFF_BASE_SECONDS * (2 ** (attempt_number - 1)))

    return DeliveryResult(False, attempts[-1].status_code, attempts)

